معطى، ABCD متوازي أضلاع. AC و BD هما قطراه. لدينا للتعبير عن المتجهات \vec{AB} و \vec{AC} بدلالة \vec{AD} و \vec{BD} ويتعين علينا أن نبين أن،
\vec{AC} + \vec{BD} = 2\vec{BC} \text{ و } \vec{AC} - \vec{BD} = 2\vec{AB}.

في المثلث \Delta ABD،
\vec{AD} = \vec{AB} + \vec{BD} \text{ [قانون المثلث]}
\therefore \vec{AB} = \vec{AD} - \vec{BD} \text{.............(i)}
مرة أخرى في المثلث ACD، \vec{AC} = \vec{AD} + \vec{DC} \text{[قانون المثلث]}
\text{[بما أن، ABCD متوازي أضلاع، فإن } \vec{DC} = \vec{AB}]
= \vec{AD} + \vec{AD} - \vec{BD} [\because \vec{AB} = \vec{AD} - \vec{BD}]
\therefore \vec{AC} = 2\vec{AD} - \vec{BD} \text{.............(ii)}
الآن، \vec{AC} + \vec{BD} = 2\vec{AD} - \vec{BD} + \vec{BD}
\text{[بإضافة } \vec{BD} \text{ إلى كلا طرفي (ii)]}
= 2 \vec{AD}
\therefore \vec{AC} + \vec{BD} = 2 \vec{BC} \text{.............(iii)}
\text{[بما أن، ABCD متوازي أضلاع، فإن } \vec{AD} = \vec{BC}]
مرة أخرى، \vec{AC} - \vec{BD} = (2\vec{AD} - \vec{BD}) - \vec{BD} \text{ [باستخدام (ii)]}
= 2\vec{AD} - 2 \vec{BD} = 2 (\vec{AD} - \vec{BD})
= 2\vec{AB} \text{ [باستخدام (i)]}
\therefore \vec{AC} - \vec{BD} = 2\vec{AB} \text{.............(iv)}
الآن، من المعادلات (i) و (ii) و (iii) و (iv) نحصل على،
\vec{AB} = \vec{AD} - \vec{BD}
\vec{AC} = 2\vec{AD} - \vec{BD}
\vec{AC} + \vec{BD} = 2\vec{BC} \text{ و } \vec{AC} - \vec{BD} = 2\vec{AB} \text{ (مُبيّن)}

